import { randomUUID } from "node:crypto";
import { link, mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import {
  type Change,
  migrateProject,
  type OpError,
  type Project,
  type ShaderDefinition,
  type ShaderDefinitionSummary,
} from "@kynimo/scene";

/** Write keys kept per project (and for `create_project`), oldest dropped first. */
export const MAX_WRITE_KEYS = 1000;

/** Project ids are generated by the store; anything else is rejected before it reaches a path. */
export const PROJECT_ID_PATTERN = /^p-[a-f0-9]{32}$/;

export const newProjectId = (): string => `p-${randomUUID().replaceAll("-", "")}`;

/**
 * The account of a local (stdio) server, and the owner of every project stored before accounts
 * existed. Remote accounts are namespaced (`user:<subject>`, see `accountForSubject`), so no
 * signed-in user can be this one.
 */
export const LOCAL_ACCOUNT = "local";

export type WriteOutcome =
  | { status: "applied"; version: number; result: WriteResult }
  | {
      status: "rejected";
      kind: "invalid" | "conflict" | "empty";
      message: string;
      errors: OpError[];
      /** The project's version at rejection; absent for `create_project`, which has no project. */
      currentVersion?: number;
    };

/** What a successful write returns. Ids are concrete, never selectors. */
export interface WriteResult {
  project_id: string;
  version: number;
  changed: boolean;
  definition?: ShaderDefinitionSummary;
  definition_created?: boolean;
  layers_added: string[];
  layers_removed: string[];
  layers_changed: string[];
  markers_added: string[];
  markers_removed: string[];
  /** Optional: outcomes stored before precompose existed have none. */
  compositions_added?: string[];
  compositions_removed?: string[];
  /** Optional: outcomes stored before asset ops existed have none. */
  assets_added?: string[];
  assets_removed?: string[];
}

/** One idempotency key and what it did. `fingerprint` identifies the request it was used with. */
export interface WriteRecord {
  actor: string;
  key: string;
  fingerprint: string;
  outcome: WriteOutcome;
}

export interface Stacks {
  undo: Change[][];
  redo: Change[][];
}

/** A project's current state: everything a write reads and replaces, apart from its keys. */
export interface ProjectState {
  id: string;
  /** Starts at 1 and increases by one on every write that changes the document. */
  version: number;
  doc: Project;
  idCounter: number;
  /** Per-actor undo/redo stacks (ADR-0010, persisted per ADR-0018). */
  history: Record<string, Stacks>;
}

/** `FileStore`'s file format: the state plus its write keys. Plain JSON. */
export interface StoredProject extends ProjectState {
  definitions?: ShaderDefinition[];
  /** Most recent last; capped at MAX_WRITE_KEYS. */
  writes: WriteRecord[];
}

export interface ProjectMeta {
  id: string;
  name: string;
  version: number;
}

/**
 * What a store knows about an idempotency key. `expired`: the key was used, but its outcome is
 * past the store's retention window (only `PostgresStore` expires keys; the local stores drop
 * the oldest keys past MAX_WRITE_KEYS, which then read as `unknown`).
 */
export type KeyLookup =
  | { status: "found"; record: WriteRecord }
  | { status: "expired" }
  | { status: "unknown" };

/** Keys an open transaction can read. */
export interface KeyReader {
  lookup(actor: string, key: string): Promise<KeyLookup>;
}

export interface ProjectTx extends KeyReader {
  /** The project as of this transaction; a copy, free to change. */
  readonly project: ProjectState;
  definitions(): Promise<ShaderDefinition[]>;
}

/** The run_script program that wrote a version (ADR-0036, ADR-0044). The document never depends on it. */
export interface ScriptRecord {
  version: number;
  source: string;
  seed: number;
}

/**
 * What one write saves: always its key record, and the new state when the project changed.
 * `script` is saved only with a `project` whose version differs from the current one, against the
 * new version; otherwise it is ignored.
 */
export interface Commit {
  record: WriteRecord;
  project?: ProjectState;
  script?: { source: string; seed: number };
  definition?: ShaderDefinition;
}

/** A transaction's result; its commit, if any, is saved atomically before the call returns. */
export interface Step<T> {
  value: T;
  commit?: Commit;
}

/**
 * Where projects live: `MemoryStore`, `FileStore` (one local process) or `PostgresStore`
 * (shared by many). A store serializes writes per project itself, so a version check and its
 * write never interleave, and saves each commit atomically: document, version snapshot, undo
 * history and key together (ADR-0029).
 */
export interface ProjectStore {
  list(): Promise<ProjectMeta[]>;
  /** Immutable shader versions, or undefined for a missing or inaccessible project. */
  listShaderDefinitions(id: string): Promise<ShaderDefinition[] | undefined>;
  get(id: string): Promise<ProjectState | undefined>;
  /** The document as it was at `version`, or undefined if the store has no such version. */
  getVersion(id: string, version: number): Promise<Project | undefined>;
  /**
   * The script that wrote `version`; with `version` undefined, the script of the highest version
   * that has one. Undefined if there is no such project (or it is another account's), the id or
   * version is invalid, or no script was saved.
   */
  getScript(id: string, version?: number): Promise<ScriptRecord | undefined>;
  /** Versions that have a script, newest first, at most `limit`. Empty for a missing project. */
  scriptVersions(id: string, limit: number): Promise<number[]>;
  /** A key's record outside a transaction. `projectId` undefined: `create_project` keys. */
  lookupWrite(projectId: string | undefined, actor: string, key: string): Promise<KeyLookup>;
  /** Runs `fn` with the project locked and saves its commit. Undefined if there is no project. */
  transact<T>(
    id: string,
    fn: (tx: ProjectTx) => Promise<Step<T>>,
  ): Promise<{ value: T } | undefined>;
  /**
   * Runs `fn` for `create_project`, whose keys are scoped to the account, and saves its commit:
   * the new project (at version 1) and its key. `fn` must call `tx.lookup` for its key before
   * committing: `PostgresStore` serializes creates with one key in that call.
   */
  create<T>(fn: (tx: KeyReader) => Promise<Step<T>>): Promise<T>;
}

/**
 * A store holding many accounts' projects. Every `ProjectStore` method acts for one account:
 * `list` shows only its projects, and another account's project reads as missing, so a caller
 * cannot tell it exists. `forAccount` returns a view on the same data for another account.
 */
export interface AccountStore extends ProjectStore {
  readonly account: string;
  forAccount(account: string): AccountStore;
}

const copy = <T>(value: T): T => structuredClone(value);

/** Runs tasks one at a time per key, in arrival order; a failed task does not block the next. */
export class KeyedMutex {
  private readonly tails = new Map<string, Promise<unknown>>();

  async run<T>(key: string, fn: () => Promise<T>): Promise<T> {
    const previous = this.tails.get(key) ?? Promise.resolve();
    const run = previous.then(fn, fn);
    const tail = run.catch(() => undefined);
    this.tails.set(key, tail);
    try {
      return await run;
    } finally {
      if (this.tails.get(key) === tail) this.tails.delete(key);
    }
  }
}

const find = (records: readonly WriteRecord[], actor: string, key: string): KeyLookup => {
  const record = records.find((r) => r.actor === actor && r.key === key);
  return record ? { status: "found", record: copy(record) } : { status: "unknown" };
};

const CREATE = "#create";

/**
 * A loaded document, migrated to the current format. When the format changed, undo history is
 * dropped: its change records describe the old format.
 */
export function migrateLoaded(
  id: string,
  doc: unknown,
  history: Record<string, Stacks>,
): { doc: Project; history: Record<string, Stacks> } {
  const migrated = migrateProject(doc);
  if (!migrated.ok)
    throw new Error(
      `project ${id} in the store is not a valid document: ${migrated.errors.map((e) => `${e.path.join(".")}: ${e.message}`).join("; ")}`,
    );
  return { doc: migrated.doc, history: migrated.from !== migrated.to ? {} : history };
}

interface MemoryEntry {
  account: string;
  state: ProjectState;
  writes: WriteRecord[];
  /** Superseded versions; the current one is `state.doc`. */
  versions: Map<number, Project>;
  definitions: ShaderDefinition[];
  /** The script that wrote each version, where there is one. */
  scripts: Map<number, { source: string; seed: number }>;
}

/** What every account view of one `MemoryStore` shares. */
interface MemoryData {
  projects: Map<string, MemoryEntry>;
  /** `create_project` keys per account. */
  creates: Map<string, WriteRecord[]>;
  mutex: KeyedMutex;
  maxWriteKeys: number;
}

export class MemoryStore implements AccountStore {
  private readonly data: MemoryData;

  /**
   * A new, empty store for `account` (default LOCAL_ACCOUNT). Given another `MemoryStore`, it is
   * a view on that store's data instead (`forAccount`).
   */
  constructor(
    options: { maxWriteKeys?: number } | MemoryStore = {},
    readonly account: string = LOCAL_ACCOUNT,
  ) {
    this.data =
      options instanceof MemoryStore
        ? options.data
        : {
            projects: new Map(),
            creates: new Map(),
            mutex: new KeyedMutex(),
            maxWriteKeys: options.maxWriteKeys ?? MAX_WRITE_KEYS,
          };
  }

  forAccount(account: string): MemoryStore {
    return new MemoryStore(this, account);
  }

  /** The project, if it exists and belongs to this account. */
  private entry(id: string): MemoryEntry | undefined {
    const entry = this.data.projects.get(id);
    return entry?.account === this.account ? entry : undefined;
  }

  async list(): Promise<ProjectMeta[]> {
    return [...this.data.projects.values()]
      .filter((e) => e.account === this.account)
      .map(({ state }) => ({ id: state.id, name: state.doc.name, version: state.version }));
  }
  async get(id: string): Promise<ProjectState | undefined> {
    const entry = this.entry(id);
    return entry && copy(entry.state);
  }
  async getVersion(id: string, version: number): Promise<Project | undefined> {
    const entry = this.entry(id);
    if (!entry) return undefined;
    const doc = version === entry.state.version ? entry.state.doc : entry.versions.get(version);
    return doc && copy(doc);
  }
  async getScript(id: string, version?: number): Promise<ScriptRecord | undefined> {
    const entry = this.entry(id);
    if (!entry) return undefined;
    if (version === undefined) {
      const latest = Math.max(0, ...entry.scripts.keys());
      return this.getScript(id, latest);
    }
    const script = entry.scripts.get(version);
    return script && { version, ...copy(script) };
  }
  async scriptVersions(id: string, limit: number): Promise<number[]> {
    const entry = this.entry(id);
    if (!entry) return [];
    return [...entry.scripts.keys()].sort((a, b) => b - a).slice(0, Math.max(0, limit));
  }
  async listShaderDefinitions(id: string): Promise<ShaderDefinition[] | undefined> {
    const entry = this.entry(id);
    return entry && copy(entry.definitions);
  }

  async lookupWrite(projectId: string | undefined, actor: string, key: string): Promise<KeyLookup> {
    if (projectId === undefined) return find(this.data.creates.get(this.account) ?? [], actor, key);
    return find(this.entry(projectId)?.writes ?? [], actor, key);
  }
  async transact<T>(
    id: string,
    fn: (tx: ProjectTx) => Promise<Step<T>>,
  ): Promise<{ value: T } | undefined> {
    return this.data.mutex.run(id, async () => {
      const entry = this.entry(id);
      if (!entry) return undefined;
      const step = await fn({
        project: copy(entry.state),
        definitions: async () => copy(entry.definitions),
        lookup: async (actor, key) => find(entry.writes, actor, key),
      });
      if (step.commit) {
        const { record, project, script, definition } = copy(step.commit);
        if (project) {
          if (project.version !== entry.state.version) {
            entry.versions.set(entry.state.version, entry.state.doc);
            if (script) entry.scripts.set(project.version, script);
          }
          entry.state = project;
        }
        if (definition !== undefined) entry.definitions.push(definition);
        entry.writes = [...entry.writes, record].slice(-this.data.maxWriteKeys);
      }
      return { value: step.value };
    });
  }
  async create<T>(fn: (tx: KeyReader) => Promise<Step<T>>): Promise<T> {
    // One lock per account: an id is never reused, so creates of different accounts can't clash.
    return this.data.mutex.run(`${CREATE}:${this.account}`, async () => {
      const creates = this.data.creates.get(this.account) ?? [];
      const step = await fn({ lookup: async (actor, key) => find(creates, actor, key) });
      if (step.commit) {
        const { record, project } = copy(step.commit);
        if (project)
          this.data.projects.set(project.id, {
            account: this.account,
            state: project,
            writes: [],
            versions: new Map(),
            scripts: new Map(),
            definitions: [],
          });
        this.data.creates.set(this.account, [...creates, record].slice(-this.data.maxWriteKeys));
      }
      return step.value;
    });
  }
}

/** Writes to a temp file and renames it over the target, so a crash never leaves half a file. */
async function writeAtomic(path: string, data: string): Promise<void> {
  const tmp = `${path}.${randomUUID()}.tmp`;
  await writeFile(tmp, data, "utf8");
  await rename(tmp, path);
}

/** A positive integer pid, or undefined for anything else (empty, partial, 0 or negative). */
const readPid = (text: string): number | undefined => {
  const pid = Number(text.trim());
  return Number.isInteger(pid) && pid > 0 && text.trim() !== "" ? pid : undefined;
};

const isAlive = (pid: number): boolean => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    // EPERM: the process exists but belongs to someone else.
    return (e as { code?: unknown }).code === "EPERM";
  }
};

const isMissing = (e: unknown) =>
  typeof e === "object" && e !== null && (e as { code?: unknown }).code === "ENOENT";

/**
 * A single-account store (LOCAL_ACCOUNT) for one local process: one JSON file per project under
 * `<dir>/projects`, superseded versions under `<dir>/versions/<id>/<n>.json`, the script that wrote
 * a version under `<dir>/scripts/<id>/<n>.json`, and `<dir>/create-keys.json`. Documents are migrated on load
 * (`migrateLoaded`).
 */
export class FileStore implements ProjectStore {
  private constructor(private readonly dir: string) {}

  /**
   * Opens `dir` for this process only. The write lock is in memory, so two processes on
   * one folder could both pass a version check and lose a write; `<dir>/.lock` refuses a second
   * owner. The lock never exists without its pid: the pid is written to a temp file that is then
   * hard-linked into place, which fails atomically if a lock exists. A lock whose pid is gone is
   * renamed away and re-read before deletion, so a racing starter never deletes a fresh lock.
   * Anything unreadable counts as held.
   */
  static async open(dir: string, pid: number = process.pid): Promise<FileStore> {
    await mkdir(dir, { recursive: true });
    const lock = join(dir, ".lock");
    const held = (detail: string) =>
      new Error(
        `${dir} is in use (${detail}). Stop the other kynimo-mcp process or use a different --dir; if no server is running, delete ${lock}`,
      );
    const tmp = join(dir, `.lock.${randomUUID()}.tmp`);
    await writeFile(tmp, String(pid), "utf8");
    try {
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          await link(tmp, lock);
          return new FileStore(dir);
        } catch (e) {
          if ((e as { code?: unknown }).code !== "EEXIST") throw e;
        }
        const owner = readPid(await readFile(lock, "utf8").catch(() => ""));
        if (owner === undefined) throw held("its lock file is unreadable");
        if (owner === pid) return new FileStore(dir);
        if (isAlive(owner)) throw held(`pid ${owner}`);
        // Stale: move it aside, and only delete it if it is still the dead owner's lock.
        const aside = join(dir, `.lock.${randomUUID()}.stale`);
        try {
          await rename(lock, aside);
        } catch (e) {
          if (isMissing(e)) continue;
          throw e;
        }
        if (readPid(await readFile(aside, "utf8").catch(() => "")) === owner) await rm(aside);
        else {
          // Another starter took the folder between our read and rename: put its lock back.
          await link(aside, lock).catch(() => undefined);
          await rm(aside, { force: true });
          throw held("another process is starting on it");
        }
      }
      throw held("its lock keeps changing");
    } finally {
      await rm(tmp, { force: true });
    }
  }

  /** Releases the folder lock. */
  async close(): Promise<void> {
    await rm(join(this.dir, ".lock"), { force: true });
  }

  private readonly mutex = new KeyedMutex();
  private projectsDir = () => join(this.dir, "projects");
  private projectPath = (id: string) => join(this.projectsDir(), `${id}.json`);
  private versionPath = (id: string, version: number) =>
    join(this.dir, "versions", id, `${version}.json`);
  private scriptDir = (id: string) => join(this.dir, "scripts", id);
  private createKeysPath = () => join(this.dir, "create-keys.json");

  async list(): Promise<ProjectMeta[]> {
    let names: string[];
    try {
      names = await readdir(this.projectsDir());
    } catch (e) {
      if (isMissing(e)) return [];
      throw e;
    }
    const metas: ProjectMeta[] = [];
    for (const name of names.sort()) {
      const id = name.endsWith(".json") ? name.slice(0, -5) : "";
      if (!PROJECT_ID_PATTERN.test(id)) continue;
      try {
        const p = await this.read(id);
        if (p) metas.push({ id: p.id, name: p.doc.name, version: p.version });
      } catch {
        // One unreadable file must not hide every other project; get_project reports it by id.
      }
    }
    return metas;
  }

  /** A JSON file, or undefined if it does not exist. */
  private async readJson(path: string, what: string): Promise<unknown> {
    let raw: string;
    try {
      raw = await readFile(path, "utf8");
    } catch (e) {
      if (isMissing(e)) return undefined;
      throw e;
    }
    try {
      return JSON.parse(raw);
    } catch (e) {
      throw new Error(
        `${what} on disk is not valid JSON: ${e instanceof Error ? e.message : String(e)}`,
      );
    }
  }

  private async read(id: string): Promise<StoredProject | undefined> {
    if (!PROJECT_ID_PATTERN.test(id)) return undefined;
    const stored = (await this.readJson(this.projectPath(id), `project ${id}`)) as
      | StoredProject
      | undefined;
    if (stored === undefined) return undefined;
    return { ...stored, id, ...migrateLoaded(id, stored.doc, stored.history) };
  }

  async get(id: string): Promise<ProjectState | undefined> {
    const stored = await this.read(id);
    if (!stored) return undefined;
    const { writes: _, definitions: _definitions, ...state } = stored;
    return state;
  }

  async getVersion(id: string, version: number): Promise<Project | undefined> {
    const current = await this.read(id);
    if (!current || !Number.isInteger(version) || version < 1) return undefined;
    if (version === current.version) return current.doc;
    const doc = await this.readJson(
      this.versionPath(id, version),
      `project ${id} version ${version}`,
    );
    return doc === undefined ? undefined : migrateLoaded(id, doc, {}).doc;
  }

  /** Version numbers that have a script file, newest first. Empty if the project is not here. */
  private async listScripts(id: string): Promise<number[]> {
    if (!PROJECT_ID_PATTERN.test(id) || !(await this.read(id))) return [];
    let names: string[];
    try {
      names = await readdir(this.scriptDir(id));
    } catch (e) {
      if (isMissing(e)) return [];
      throw e;
    }
    return names
      .filter((n) => /^\d+\.json$/.test(n))
      .map((n) => Number.parseInt(n, 10))
      .filter((v) => Number.isSafeInteger(v))
      .sort((a, b) => b - a);
  }

  async getScript(id: string, version?: number): Promise<ScriptRecord | undefined> {
    if (!PROJECT_ID_PATTERN.test(id)) return undefined;
    let v = version;
    if (v === undefined) v = (await this.listScripts(id))[0];
    else if (!Number.isInteger(v) || v < 1 || !(await this.read(id))) return undefined;
    if (v === undefined) return undefined;
    const script = (await this.readJson(
      join(this.scriptDir(id), `${v}.json`),
      `project ${id} script ${v}`,
    )) as { source: string; seed: number } | undefined;
    return script && { version: v, source: script.source, seed: script.seed };
  }

  async scriptVersions(id: string, limit: number): Promise<number[]> {
    return (await this.listScripts(id)).slice(0, Math.max(0, limit));
  }

  async lookupWrite(projectId: string | undefined, actor: string, key: string): Promise<KeyLookup> {
    if (projectId === undefined) return find(await this.createRecords(), actor, key);
    return find((await this.read(projectId))?.writes ?? [], actor, key);
  }

  async listShaderDefinitions(id: string): Promise<ShaderDefinition[] | undefined> {
    const stored = await this.read(id);
    return stored && (stored.definitions ?? []);
  }

  private async put(project: StoredProject): Promise<void> {
    if (!PROJECT_ID_PATTERN.test(project.id)) throw new Error(`invalid project id ${project.id}`);
    await mkdir(this.projectsDir(), { recursive: true });
    await writeAtomic(this.projectPath(project.id), JSON.stringify(project));
  }

  /**
   * Saves the superseded version's snapshot first, then the project file, then the script. A crash
   * between the first two leaves a snapshot of a version that really existed, which the next write
   * overwrites. The script goes last so a crash can lose it but never leave one at a version that
   * was never committed; the document never depends on it.
   */
  async transact<T>(
    id: string,
    fn: (tx: ProjectTx) => Promise<Step<T>>,
  ): Promise<{ value: T } | undefined> {
    return this.mutex.run(id, async () => {
      const stored = await this.read(id);
      if (!stored) return undefined;
      const { writes, definitions, ...state } = stored;
      const step = await fn({
        project: copy(state),
        definitions: async () => copy(definitions ?? []),
        lookup: async (actor, key) => find(writes, actor, key),
      });
      if (step.commit) {
        const { record, project = state } = step.commit;
        if (project.version !== state.version) {
          await mkdir(join(this.dir, "versions", id), { recursive: true });
          await writeAtomic(this.versionPath(id, state.version), JSON.stringify(state.doc));
        }
        const nextDefinitions =
          step.commit.definition === undefined
            ? definitions
            : [...(definitions ?? []), step.commit.definition];
        await this.put({
          ...project,
          id,
          writes: [...writes, record].slice(-MAX_WRITE_KEYS),
          ...(nextDefinitions === undefined ? {} : { definitions: nextDefinitions }),
        });
        if (project.version !== state.version && step.commit.script) {
          const { source, seed } = step.commit.script;
          await mkdir(this.scriptDir(id), { recursive: true });
          await writeAtomic(
            join(this.scriptDir(id), `${project.version}.json`),
            JSON.stringify({ source, seed }),
          );
        }
      }
      return { value: step.value };
    });
  }

  private async createRecords(): Promise<WriteRecord[]> {
    return (
      ((await this.readJson(this.createKeysPath(), "create-keys.json")) as
        | WriteRecord[]
        | undefined) ?? []
    );
  }

  /**
   * Two files: the project, then its key. A crash between them leaves a project without its key,
   * so a retry creates a second one; `PostgresStore` saves both in one transaction.
   */
  async create<T>(fn: (tx: KeyReader) => Promise<Step<T>>): Promise<T> {
    return this.mutex.run(CREATE, async () => {
      const records = await this.createRecords();
      const step = await fn({ lookup: async (actor, key) => find(records, actor, key) });
      if (step.commit) {
        const { record, project } = step.commit;
        if (project) await this.put({ ...project, writes: [] });
        await mkdir(this.dir, { recursive: true });
        await writeAtomic(
          this.createKeysPath(),
          JSON.stringify([...records, record].slice(-MAX_WRITE_KEYS)),
        );
      }
      return step.value;
    });
  }
}
